(function () {
  // ====== CẤU HÌNH ======
  // URL Web App của Apps Script (khớp với backend.gs)
  const API_URL = "https://script.google.com/macros/s/AKfycbyjEIFQ3C4hLH5v8ovoPwDbQMaMMTZOhR1cVd2F2X9MlRGUBjLV5DBZphxMXcjLuaLl/exec";
  // Tên tab/sheet lưu dữ liệu — PHẢI khớp đúng tên sheet trong Google Sheet
  const SHEET_NAME = "KHÁCH MỜI";

  const listEl = document.getElementById("wsc-list");

  // ====== TRẠNG THÁI AUTO-SCROLL ======
  let scrollY = 0;
  let isPaused = true;      // đang tạm dừng auto-scroll (do người dùng đang thao tác / cuộn ra khỏi khung nhìn)
  let isAtBottom = false;   // đang ở đáy danh sách, chờ để cuộn lại lên đầu
  let resumeTimer, pauseTimer, animFrame;

  // Khi khung danh sách vào/ra khỏi khung nhìn (viewport)
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        const items = listEl.querySelectorAll(".wsc-item");
        if (items.length >= 6) {
          clearTimeout(pauseTimer);
          pauseTimer = setTimeout(() => {
            isPaused = false;
            startAutoScroll();
          }, 2000);
        }
      } else {
        isPaused = true;
        cancelAnimationFrame(animFrame);
        clearTimeout(pauseTimer);
      }
    });
  }, { threshold: 0.3 });

  // ====== TẢI DANH SÁCH LỜI CHÚC ======
  async function loadWishes() {
    try {
      // encodeURIComponent để tránh ký tự đặc biệt (&, dấu cách, ...) trong tên sheet
      // làm hỏng query string khi gửi lên Apps Script.
      const res = await fetch(`${API_URL}?tabName=${encodeURIComponent(SHEET_NAME)}`);
      const data = await res.json();

      listEl.innerHTML = "";

      if (!data || data.length === 0) {
        listEl.innerHTML = "<div class='wsc-loading'>Chưa có lời chúc nào.</div>";
        return;
      }

      const wishes = data.filter(item => item.name && item.message).reverse();

      wishes.forEach((item) => {
        const el = document.createElement("div");
        el.className = "wsc-item";
        el.innerHTML = `<strong>${item.name}</strong><span>${item.message}</span>`;
        listEl.appendChild(el);
      });

      if (wishes.length >= 6) {
        observer.observe(listEl);
      } else {
        observer.unobserve(listEl);
        cancelAnimationFrame(animFrame);
        isPaused = true;
      }
    } catch (err) {
      listEl.innerHTML = "<div class='wsc-loading'>Không thể tải lời chúc lúc này.</div>";
    }
  }

  // ====== AUTO-SCROLL DANH SÁCH ======
  function startAutoScroll() {
    if (isPaused || isAtBottom) return;

    function step() {
      if (isPaused || isAtBottom) return;
      scrollY += 0.5;

      if (scrollY >= listEl.scrollHeight - listEl.clientHeight) {
        isAtBottom = true;
        listEl.scrollTop = listEl.scrollHeight;
        setTimeout(() => {
          scrollY = 0;
          listEl.scrollTop = 0;
          isAtBottom = false;
          animFrame = requestAnimationFrame(step);
        }, 6000);
      } else {
        listEl.scrollTop = scrollY;
        animFrame = requestAnimationFrame(step);
      }
    }

    cancelAnimationFrame(animFrame);
    animFrame = requestAnimationFrame(step);
  }

  // Khi người dùng chạm/kéo/cuộn danh sách -> tạm dừng auto-scroll, sau 6s mới chạy lại
  function onUserInteract() {
    const items = listEl.querySelectorAll(".wsc-item");
    isPaused = true;
    isAtBottom = false;
    cancelAnimationFrame(animFrame);
    clearTimeout(resumeTimer);
    clearTimeout(pauseTimer);

    if (items.length >= 6) {
      resumeTimer = setTimeout(() => {
        isPaused = false;
        scrollY = listEl.scrollTop;
        startAutoScroll();
      }, 6000);
    }
  }

  listEl.addEventListener("touchstart", onUserInteract, { passive: true });
  listEl.addEventListener("mousedown", onUserInteract);
  listEl.addEventListener("wheel", onUserInteract, { passive: true });

  // ====== POPUP THÀNH CÔNG ======
  globalThis.onclick_ok = () => {
    document.getElementById("wsc-success-msg").style.display = "none";
  };
  document.getElementById("wsc-ok-btn").onclick = globalThis.onclick_ok;

  // ====== HIỆU ỨNG PHÁO HOA ======
  function playFireworks() {
    const canvas = document.getElementById("wsc-fireworks");
    const ctx = canvas.getContext("2d");
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    canvas.style.display = "block";

    let particles = [];
    for (let i = 0; i < 60; i++) {
      particles.push({
        x: canvas.width / 2,
        y: canvas.height / 2,
        r: 3 * Math.random() + 1,
        color: "rgba(170, 1, 1, 1)",
        v: { x: 12 * (Math.random() - 0.5), y: 12 * (Math.random() - 0.5) },
        a: 1
      });
    }

    (function animate() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      particles.forEach((p, i) => {
        p.x += p.v.x;
        p.y += p.v.y;
        p.a -= 0.015;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, 2 * Math.PI);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.a;
        ctx.fill();
        if (p.a <= 0) particles.splice(i, 1);
      });
      if (particles.length > 0) {
        requestAnimationFrame(animate);
      } else {
        canvas.style.display = "none";
      }
    })();
  }

  // ====== GỬI RSVP ======
  document.getElementById("wsc-sendBtn").onclick = async function () {
    const nameInput = document.getElementById("wsc-name");
    const messageInput = document.getElementById("wsc-message");
    const attendanceSelect = document.getElementById("wsc-attendance");
    const successMsg = document.getElementById("wsc-success-msg");
    const btn = this;

    if (!nameInput.value.trim() || !messageInput.value.trim()) {
      alert("Vui lòng nhập tên và lời chúc nhé!");
      return;
    }

    btn.disabled = true;
    btn.innerText = "Đang gửi...";

    await fetch(API_URL, {
      method: "POST",
      mode: "no-cors",
      body: new URLSearchParams({
        name: nameInput.value,
        message: messageInput.value,
        attendance: attendanceSelect.value,
        tabName: SHEET_NAME
      })
    });

    playFireworks();
    successMsg.style.display = "flex";

    nameInput.value = "";
    messageInput.value = "";
    attendanceSelect.selectedIndex = 0;

    setTimeout(async () => {
      await loadWishes();
    }, 1000);

    btn.disabled = false;
    btn.innerText = "💌 Gửi xác nhận";
  };

  // Tải lời chúc ngay khi trang mở
  loadWishes();
})();
